import{_ as r,a0 as l,w as p,s as o,I as s,a1 as n,A as t,x as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何在 Fedora 30 Server 上安裝 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 30 Server 上安裝 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 30 Server 上安裝 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 30 Server 上安裝 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20190602 How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server","title":"如何在 Fedora 30 Server 上安裝 LEMP（Linux、Nginx、MariaDB、PHP）","tag":"201912","desc":""},"relativePath":"201912/20190602 How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server.md","filePath":"[post].md"}'),h={name:"201912/20190602 How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server.md"};function g(u,a,c,m,b,k){const e=l("Link");return p(),o("div",null,[s("p",null,[n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...a[0]||(a[0]=[i("#",-1)])]),_:1}),a[5]||(a[5]=i(": subject: (How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server) ",-1)),n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...a[1]||(a[1]=[i("#",-1)])]),_:1}),a[6]||(a[6]=i(": via: (",-1)),n(e,{href:"https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/"},{default:t(()=>[...a[2]||(a[2]=[i("https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/",-1)])]),_:1}),a[7]||(a[7]=i(") ",-1)),n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...a[3]||(a[3]=[i("#",-1)])]),_:1}),a[8]||(a[8]=i(": author: (Pradeep Kumar ",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...a[4]||(a[4]=[i("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),a[9]||(a[9]=i(")",-1))]),a[28]||(a[28]=s("h1",{id:"如何在-fedora-30-server-上安裝-lemp-linux、nginx、mariadb、php",tabindex:"-1"},[i("如何在 Fedora 30 Server 上安裝 LEMP（Linux、Nginx、MariaDB、PHP） "),s("a",{class:"header-anchor",href:"#如何在-fedora-30-server-上安裝-lemp-linux、nginx、mariadb、php","aria-label":"Permalink to “如何在 Fedora 30 Server 上安裝 LEMP（Linux、Nginx、MariaDB、PHP）”"},"​")],-1)),a[29]||(a[29]=s("p",null,[i("在這篇文章中，我們將看看如何在 Fedora 30 Server 上安裝 "),s("strong",null,"LEMP"),i(" 。LEMP 代表：")],-1)),a[30]||(a[30]=s("ul",null,[s("li",null,"L -> Linux"),s("li",null,"E -> Nginx"),s("li",null,"M -> Maria DB"),s("li",null,"P -> PHP")],-1)),s("p",null,[a[11]||(a[11]=i("我假設 ",-1)),n(e,{href:"https://www.linuxtechi.com/fedora-30-workstation-installation-guide/"},{default:t(()=>[...a[10]||(a[10]=[i("Fedora 30",-1)])]),_:1}),a[12]||(a[12]=i(" 已經安裝在你的電腦系統上。",-1))]),a[31]||(a[31]=d(`<p><img src="https://img.linux.net.cn/data/attachment/album/201912/01/103537wil7hd36dhcxdh03.jpg" alt=""></p><p>LEMP 是一組強大的軟件設置集合，它安裝在一個 Linux 服務器上以幫助使用流行的開發平台來構建網站，LEMP 是 LAMP 的一個變種，在其中不是 Apache ，而是使用 EngineX（Nginx），此外，使用 MariaDB 代替 MySQL。這篇入門指南是一個安裝 Nginx、Maria DB 和 PHP 的獨立指南的作品集合。</p><h3 id="在-fedora-30-server-上安裝-nginx、php-7-3-和-php-fpm" tabindex="-1">在 Fedora 30 Server 上安裝 Nginx、PHP 7.3 和 PHP-FPM <a class="header-anchor" href="#在-fedora-30-server-上安裝-nginx、php-7-3-和-php-fpm" aria-label="Permalink to “在 Fedora 30 Server 上安裝 Nginx、PHP 7.3 和 PHP-FPM”">​</a></h3><p>讓我們看看如何在 Fedora 30 Server 上安裝 Nginx 和 PHP 以及 PHP FPM。</p><h4 id="步驟-1-切換到-root-用户" tabindex="-1">步驟 1) 切換到 root 用户 <a class="header-anchor" href="#步驟-1-切換到-root-用户" aria-label="Permalink to “步驟 1) 切換到 root 用户”">​</a></h4><p>在系統上安裝 Nginx 的第一步是切換到 root 用户。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]$ sudo -i</span></span>
<span class="line"><span>[sudo] password for pkumar:</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步驟-2-使用-dnf-命令安裝-nginx、php-7-3-和-php-fpm" tabindex="-1">步驟 2) 使用 dnf 命令安裝 Nginx、PHP 7.3 和 PHP FPM <a class="header-anchor" href="#步驟-2-使用-dnf-命令安裝-nginx、php-7-3-和-php-fpm" aria-label="Permalink to “步驟 2) 使用 dnf 命令安裝 Nginx、PHP 7.3 和 PHP FPM”">​</a></h4><p>使用下面的 <code>dnf</code> 命令安裝 Nginx：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install nginx php php-fpm php-common -y</span></span></code></pre></div><h4 id="步驟-3-安裝額外的-php-模組" tabindex="-1">步驟 3) 安裝額外的 PHP 模組 <a class="header-anchor" href="#步驟-3-安裝額外的-php-模組" aria-label="Permalink to “步驟 3) 安裝額外的 PHP 模組”">​</a></h4><p>PHP 的默認安裝僅自帶基本模組和最需要的模組，如果你需要額外的模組，像 PHP 支持的 GD、XML、命令列接口、Zend OPCache 功能等等，你總是能夠選擇你的軟件包，並一次性安裝所有的東西。查看下面的示例命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# sudo dnf install php-opcache php-pecl-apcu php-cli php-pear php-pdo php-pecl-mongodb php-pecl-redis php-pecl-memcache php-pecl-memcached php-gd php-mbstring php-mcrypt php-xml -y</span></span></code></pre></div><h4 id="步驟-4-開始-啓用-nginx-和-php-fpm-服務" tabindex="-1">步驟 4) 開始 &amp; 啓用 Nginx 和 PHP-fpm 服務 <a class="header-anchor" href="#步驟-4-開始-啓用-nginx-和-php-fpm-服務" aria-label="Permalink to “步驟 4) 開始 &amp; 啓用 Nginx 和 PHP-fpm 服務”">​</a></h4><p>使用下面的命令來開始並啓用 Nginx 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start nginx &amp;&amp; systemctl enable nginx</span></span>
<span class="line"><span>Created symlink /etc/systemd/system/multi-user.target.wants/nginx.service → /usr/lib/systemd/system/nginx.service.</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的命令來開始並啓用 PHP-FPM 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start php-fpm &amp;&amp; systemctl enable php-fpm</span></span>
<span class="line"><span>Created symlink /etc/systemd/system/multi-user.target.wants/php-fpm.service → /usr/lib/systemd/system/php-fpm.service.</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步驟-5-核實-nginx-web-服務-和-php-安裝" tabindex="-1">步驟 5) 核實 Nginx (Web 服務) 和 PHP 安裝 <a class="header-anchor" href="#步驟-5-核實-nginx-web-服務-和-php-安裝" aria-label="Permalink to “步驟 5) 核實 Nginx (Web 服務) 和 PHP 安裝”">​</a></h4><p>注意：假使操作系統防火牆是啓用的，並運行在你的 Fedora 30 系統上，那麼使用下面的命令來准許 80 和 443 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-service=http</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-service=https</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --reload</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>打開網頁瀏覽器，輸入下面的 URL： <code>http://&lt;Your-Server-IP&gt;</code> 。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Test-Page-HTTP-Server-Fedora-30.jpg" alt="Test-Page-HTTP-Server-Fedora-30"></p><p>上面的屏幕證實 Nginx 已經成功地安裝。</p><p>現在，讓我們核實 PHP 安裝，使用下面的命令創建一個測試 php 頁（<code>info.php</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# echo &quot;&lt;?php phpinfo(); ?&gt;&quot; &gt; /usr/share/nginx/html/info.php</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>在網頁瀏覽器中輸入下面的 URL， <code>http://&lt;Your-Server-IP&gt;/info.php</code></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Php-info-page-fedora30.jpg" alt="Php-info-page-fedora30"></p><p>上面的頁面驗證 PHP 7.3.5 已經被成功地安裝。現在，讓我們安裝 MariaDB 資料庫服務器。</p><h3 id="在-fedora-30-上安裝-mariadb" tabindex="-1">在 Fedora 30 上安裝 MariaDB <a class="header-anchor" href="#在-fedora-30-上安裝-mariadb" aria-label="Permalink to “在 Fedora 30 上安裝 MariaDB”">​</a></h3><p>MariaDB 是 MySQL 資料庫的一個極好的替代品，因為它的工作方式與 MySQL 非常類似，並且兼容性也與 MySQL 一致。讓我們看看在 Fedora 30 Server 上安裝 MariaDB 的步驟。</p><h4 id="步驟-1-切換到-root-用户-1" tabindex="-1">步驟 1) 切換到 root 用户 <a class="header-anchor" href="#步驟-1-切換到-root-用户-1" aria-label="Permalink to “步驟 1) 切換到 root 用户”">​</a></h4><p>在系統上安裝 MariaDB 的第一步是切換到 root 用户，或者你可以使用有 root 權限的本地用户。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# sudo -i</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步驟-2-使用-dnf-命令安裝-mariadb-10-3-的最新版本" tabindex="-1">步驟 2) 使用 dnf 命令安裝 MariaDB（10.3）的最新版本 <a class="header-anchor" href="#步驟-2-使用-dnf-命令安裝-mariadb-10-3-的最新版本" aria-label="Permalink to “步驟 2) 使用 dnf 命令安裝 MariaDB（10.3）的最新版本”">​</a></h4><p>在 Fedora 30 Server 上使用下面的命令來安裝 MariaDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install mariadb-server -y</span></span></code></pre></div><h4 id="步驟-3-開啓並啓用-mariadb-服務" tabindex="-1">步驟 3) 開啓並啓用 MariaDB 服務 <a class="header-anchor" href="#步驟-3-開啓並啓用-mariadb-服務" aria-label="Permalink to “步驟 3) 開啓並啓用 MariaDB 服務”">​</a></h4><p>在步驟 2 中成功地安裝 MariaDB 後，接下來的步驟是開啓 MariaDB 服務。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start mariadb.service ; systemctl enable mariadb.service</span></span></code></pre></div><h4 id="步驟-4-保護安裝好的-mariadb" tabindex="-1">步驟 4) 保護安裝好的 MariaDB <a class="header-anchor" href="#步驟-4-保護安裝好的-mariadb" aria-label="Permalink to “步驟 4) 保護安裝好的 MariaDB”">​</a></h4><p>當我們安裝 MariaDB 服務器時，因為默認情況下沒有 root 密碼，在資料庫中也會創建匿名用户。因此，要保護安裝好的 MariaDB，運行下面的 <code>mysql_secure_installation</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# mysql_secure_installation</span></span></code></pre></div><p>接下來你將被提示一些問題，僅回答下面展示的問題：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Secure-MariaDB-Installation-Part1.jpg" alt="Secure-MariaDB-Installation-Part1"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Secure-MariaDB-Installation-Part2.jpg" alt="Secure-MariaDB-Installation-Part2"></p><h4 id="步驟-5-測試-mariadb-安裝" tabindex="-1">步驟 5) 測試 MariaDB 安裝 <a class="header-anchor" href="#步驟-5-測試-mariadb-安裝" aria-label="Permalink to “步驟 5) 測試 MariaDB 安裝”">​</a></h4><p>在你安裝後，你總是能夠測試是否 MariaDB 被成功地安裝在 Fedora 30 Server 上。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# mysql -u root -p</span></span>
<span class="line"><span>Enter password:</span></span></code></pre></div><p>接下來，你將被提示一個密碼。輸入在保護安裝好的 MariaDB 期間你設置的密碼，接下來你可以看到 MariaDB 歡迎屏幕。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Welcome to the MariaDB monitor.  Commands end with ; or \\g.</span></span>
<span class="line"><span>Your MariaDB connection id is 17</span></span>
<span class="line"><span>Server version: 10.3.12-MariaDB MariaDB Server</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Copyright (c) 2000, 2018, Oracle, MariaDB Corporation Ab and others.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Type &#39;help;&#39; or &#39;\\h&#39; for help. Type &#39;\\c&#39; to clear the current input statement.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MariaDB [(none)]&gt;</span></span></code></pre></div><p>最後，我們已經在你的 Fedora 30 Server 上成功地完成安裝 LEMP（Linux、Nginx、MariaDB 和 PHP）的所有工作。請在下面的反饋部分發布你的評論和建議，我們將盡快在後面回應。</p><hr>`,53)),s("p",null,[a[14]||(a[14]=i("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/"},{default:t(()=>[...a[13]||(a[13]=[i("https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/",-1)])]),_:1})]),s("p",null,[a[19]||(a[19]=i("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...a[15]||(a[15]=[i("Pradeep Kumar",-1)])]),_:1}),a[20]||(a[20]=i(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[16]||(a[16]=[i("lujun9972",-1)])]),_:1}),a[21]||(a[21]=i(" 譯者：",-1)),n(e,{href:"https://github.com/robsean"},{default:t(()=>[...a[17]||(a[17]=[i("robsean",-1)])]),_:1}),a[22]||(a[22]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...a[18]||(a[18]=[i("wxy",-1)])]),_:1})]),s("p",null,[a[25]||(a[25]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[23]||(a[23]=[i("LCTT",-1)])]),_:1}),a[26]||(a[26]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...a[24]||(a[24]=[i("Linux中國",-1)])]),_:1}),a[27]||(a[27]=i(" 榮譽推出",-1))])])}const M=r(h,[["render",g]]);export{P as __pageData,M as default};
